# --- your code ---
class MinStack:
    def __init__(self):
        self.items = []                  # (value, minimum so far) pairs

    def push(self, x: int) -> None:
        low = min(x, self.items[-1][1]) if self.items else x
        self.items.append((x, low))

    def pop(self) -> int:
        return self.items.pop()[0]

    def top(self) -> int:
        return self.items[-1][0]

    def get_min(self) -> int:
        return self.items[-1][1]


# --- provided: do not edit ---
def run_stack(ops: list[list]) -> list:
    stack = MinStack()
    return [getattr(stack, name)(*args) for name, *args in ops]
